"use client";

/**
 * PunkRecordsCore
 * ----------------
 * A motion-preset renderer for VegaRecords' AnimatedBackground system.
 *
 * Concept: a massive central "brain" — the data core — surrounded by
 * orbiting memory nodes grouped into resource clusters, with animated
 * knowledge-stream pulses traveling along the connections back to the
 * core, and a thin outer ring of information satellites.
 */

import { useEffect, useRef } from "react";

/* ------------------------------------------------------------------ */
/* Renderer class — plain Canvas2D                                    */
/* ------------------------------------------------------------------ */

export class PunkRecordsCoreRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("PunkRecordsCore: 2D context unavailable");
    this.ctx = ctx;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);

    this.width = 0;
    this.height = 0;
    this.center = { x: 0, y: 0 };
    this.coreRadius = 0;

    this.nodes = [];
    this.satellites = [];
    this.pulses = [];
    this.clusterCount = 5;

    this.rafId = null;
    this.startTime = performance.now();
    this.lastFrameTime = performance.now();

    this.prefersReducedMotion =
      typeof window !== "undefined" &&
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

    this.primary = "#7c5cff";
    this.secondary = "#22d3ee";

    this.readThemeColors();
    this.resize();
    this.seed();
  }

  readThemeColors() {
    if (typeof window === "undefined") return;
    const styles = getComputedStyle(document.documentElement);
    const p = styles.getPropertyValue("--primary").trim();
    const s = styles.getPropertyValue("--secondary").trim();
    if (p) this.primary = p;
    if (s) this.secondary = s;
  }

  resize = () => {
    const rect = this.canvas.parentElement?.getBoundingClientRect() ?? {
      width: window.innerWidth,
      height: window.innerHeight,
    };
    this.width = rect.width;
    this.height = rect.height;
    this.canvas.width = this.width * this.dpr;
    this.canvas.height = this.height * this.dpr;
    this.canvas.style.width = `${this.width}px`;
    this.canvas.style.height = `${this.height}px`;
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);

    this.center = { x: this.width / 2, y: this.height / 2 };
    this.coreRadius = Math.max(48, Math.min(this.width, this.height) * 0.075);
  };

  seed() {
    const nodeCount = Math.round(
      Math.max(18, Math.min(this.width, this.height) / 22)
    );
    const maxOrbit = Math.min(this.width, this.height) * 0.42;
    const minOrbit = this.coreRadius * 2.2;

    this.nodes = Array.from({ length: nodeCount }, (_, i) => {
      const clusterId = i % this.clusterCount;
      const clusterAngle = (clusterId / this.clusterCount) * Math.PI * 2;
      const angleJitter = (Math.random() - 0.5) * (Math.PI / this.clusterCount) * 1.6;
      return {
        angle: clusterAngle + angleJitter,
        angularSpeed: (Math.random() * 0.06 + 0.015) * (Math.random() < 0.5 ? -1 : 1),
        radius: minOrbit + Math.random() * (maxOrbit - minOrbit),
        radiusJitterPhase: Math.random() * Math.PI * 2,
        size: 2.5 + Math.random() * 3.5,
        clusterId,
        pulsePhase: Math.random() * Math.PI * 2,
      };
    });

    this.satellites = Array.from({ length: 10 }, () => ({
      angle: Math.random() * Math.PI * 2,
      angularSpeed: (Math.random() * 0.03 + 0.008) * (Math.random() < 0.5 ? -1 : 1),
      radius: maxOrbit * (1.08 + Math.random() * 0.18),
      size: 1.5 + Math.random() * 1.5,
    }));

    this.pulses = Array.from({ length: Math.round(nodeCount * 0.6) }, () =>
      this.spawnPulse()
    );
  }

  spawnPulse() {
    return {
      nodeIndex: Math.floor(Math.random() * this.nodes.length),
      progress: Math.random(),
      speed: 0.15 + Math.random() * 0.25,
      outward: Math.random() < 0.5,
    };
  }

  nodePosition(node, t) {
    const wobble = Math.sin(t * 0.4 + node.radiusJitterPhase) * (this.coreRadius * 0.15);
    const r = node.radius + wobble;
    const a = node.angle + t * node.angularSpeed;
    return {
      x: this.center.x + Math.cos(a) * r,
      y: this.center.y + Math.sin(a) * r,
    };
  }

  hexToRgba(hex, alpha) {
    let h = hex.replace("#", "");
    if (h.length === 3) h = h.split("").map((c) => c + c).join("");
    const int = parseInt(h, 16);
    if (Number.isNaN(int)) return `rgba(124,92,255,${alpha})`;
    const r = (int >> 16) & 255;
    const g = (int >> 8) & 255;
    const b = int & 255;
    return `rgba(${r},${g},${b},${alpha})`;
  }

  drawCore(t) {
    const { ctx, center, coreRadius } = this;
    const pulse = 1 + Math.sin(t * 1.1) * 0.04;
    const r = coreRadius * pulse;

    // Outer glow
    const glow = ctx.createRadialGradient(
      center.x, center.y, r * 0.2,
      center.x, center.y, r * 2.6
    );
    glow.addColorStop(0, this.hexToRgba(this.primary, 0.35));
    glow.addColorStop(1, this.hexToRgba(this.primary, 0));
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(center.x, center.y, r * 2.6, 0, Math.PI * 2);
    ctx.fill();

    // Wireframe sphere
    const latitudes = 5;
    for (let i = 0; i < latitudes; i++) {
      const frac = (i + 1) / (latitudes + 1);
      const ellipseH = r * Math.sin(frac * Math.PI);
      const skew = Math.cos(t * 0.25 + i) * 0.6;
      ctx.save();
      ctx.translate(center.x, center.y);
      ctx.scale(1, 0.42 + 0.1 * Math.sin(t * 0.2 + i));
      ctx.rotate(t * 0.06 * (i % 2 === 0 ? 1 : -1));
      ctx.strokeStyle = this.hexToRgba(this.secondary, 0.18 + 0.1 * Math.abs(skew));
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.ellipse(0, 0, r, ellipseH, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    // Solid inner core
    const core = ctx.createRadialGradient(
      center.x - r * 0.3, center.y - r * 0.3, r * 0.1,
      center.x, center.y, r
    );
    core.addColorStop(0, this.hexToRgba(this.secondary, 0.9));
    core.addColorStop(0.5, this.hexToRgba(this.primary, 0.85));
    core.addColorStop(1, this.hexToRgba(this.primary, 0.15));
    ctx.fillStyle = core;
    ctx.beginPath();
    ctx.arc(center.x, center.y, r, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = this.hexToRgba(this.secondary, 0.6);
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(center.x, center.y, r, 0, Math.PI * 2);
    ctx.stroke();
  }

  drawConnections(t) {
    const { ctx, center } = this;
    for (const node of this.nodes) {
      const pos = this.nodePosition(node, t);
      const clusterHue =
        node.clusterId % 2 === 0 ? this.primary : this.secondary;
      ctx.strokeStyle = this.hexToRgba(clusterHue, 0.1);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(center.x, center.y);
      const midX = (center.x + pos.x) / 2 + Math.sin(t * 0.3 + node.pulsePhase) * 12;
      const midY = (center.y + pos.y) / 2 + Math.cos(t * 0.3 + node.pulsePhase) * 12;
      ctx.quadraticCurveTo(midX, midY, pos.x, pos.y);
      ctx.stroke();
    }

    for (let c = 0; c < this.clusterCount; c++) {
      const clusterNodes = this.nodes.filter((n) => n.clusterId === c);
      for (let i = 0; i < clusterNodes.length - 1; i++) {
        const a = this.nodePosition(clusterNodes[i], t);
        const b = this.nodePosition(clusterNodes[i + 1], t);
        ctx.strokeStyle = this.hexToRgba(this.secondary, 0.06);
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();
      }
    }
  }

  drawNodes(t) {
    const { ctx } = this;
    for (const node of this.nodes) {
      const pos = this.nodePosition(node, t);
      const glowPulse = 0.5 + 0.5 * Math.sin(t * 1.6 + node.pulsePhase);
      const color = node.clusterId % 2 === 0 ? this.secondary : this.primary;

      ctx.fillStyle = this.hexToRgba(color, 0.15 + glowPulse * 0.15);
      ctx.beginPath();
      ctx.arc(pos.x, pos.y, node.size * (2.2 + glowPulse), 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = this.hexToRgba(color, 0.85);
      ctx.beginPath();
      ctx.arc(pos.x, pos.y, node.size, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  drawPulses(t, dtSeconds) {
    const { ctx, center } = this;
    for (const pulse of this.pulses) {
      const node = this.nodes[pulse.nodeIndex];
      if (!node) continue;
      const target = this.nodePosition(node, t);
      const from = pulse.outward ? center : target;
      const to = pulse.outward ? target : center;

      pulse.progress += dtSeconds * pulse.speed;
      if (pulse.progress >= 1) {
        Object.assign(pulse, this.spawnPulse());
        continue;
      }

      const x = from.x + (to.x - from.x) * pulse.progress;
      const y = from.y + (to.y - from.y) * pulse.progress;
      const color = node.clusterId % 2 === 0 ? this.secondary : this.primary;
      const fade = Math.sin(pulse.progress * Math.PI);

      ctx.fillStyle = this.hexToRgba(color, 0.9 * fade);
      ctx.beginPath();
      ctx.arc(x, y, 2 + fade * 1.5, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  drawSatellites(t) {
    const { ctx, center } = this;

    ctx.strokeStyle = this.hexToRgba(this.secondary, 0.06);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(center.x, center.y, this.satellites[0]?.radius ?? 0, 0, Math.PI * 2);
    ctx.stroke();

    for (const sat of this.satellites) {
      const a = sat.angle + t * sat.angularSpeed;
      const x = center.x + Math.cos(a) * sat.radius;
      const y = center.y + Math.sin(a) * sat.radius;
      ctx.fillStyle = this.hexToRgba(this.secondary, 0.55);
      ctx.beginPath();
      ctx.arc(x, y, sat.size, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  frame = (now) => {
    const t = (now - this.startTime) / 1000;
    const dtSeconds = Math.min((now - this.lastFrameTime) / 1000, 0.05);
    this.lastFrameTime = now;

    this.ctx.clearRect(0, 0, this.width, this.height);
    this.drawConnections(t);
    this.drawSatellites(t);
    this.drawPulses(t, dtSeconds);
    this.drawNodes(t);
    this.drawCore(t);

    if (!this.prefersReducedMotion) {
      this.rafId = requestAnimationFrame(this.frame);
    }
  };

  start() {
    this.lastFrameTime = performance.now();
    this.startTime = performance.now();
    if (this.prefersReducedMotion) {
      this.frame(performance.now());
      return;
    }
    this.rafId = requestAnimationFrame(this.frame);
  }

  stop() {
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }

  destroy() {
    this.stop();
  }
}

/* ------------------------------------------------------------------ */
/* React wrapper component                                            */
/* ------------------------------------------------------------------ */

export default function PunkRecordsCoreCanvas({ className = "" }) {
  const canvasRef = useRef(null);
  const rendererRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const renderer = new PunkRecordsCoreRenderer(canvas);
    rendererRef.current = renderer;
    renderer.start();

    const handleResize = () => {
      renderer.resize();
    };
    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
      renderer.destroy();
      rendererRef.current = null;
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className={`absolute inset-0 h-full w-full pointer-events-none ${className}`}
      aria-hidden="true"
    />
  );
}